('campus-mobility-v1','1.0','校园出行高峰诊断',
 '读取 mobility.csv，按时段和站点汇总上车人数与平均等待时间。识别一个高峰时段，比较两个站点，并对缺失或异常记录说明处理方法。交付可复现脚本、汇总表和一条调度建议。',
 '[]','[]','{"bundle":"campus-mobility-v1","minutes":40,"task_type":"时序分析","difficulty":"中级","ai_allowed":true,"goal":"从站点与时段数据中定位高峰，并用可核对的汇总给出建议。","attribution":"项目自制教学数据 · CC BY 4.0","materials":["mobility.csv"],"deliverables":["Python 脚本","站点时段汇总表","异常处理记录","调度建议"],"result_label":"站点时段汇总表","check_label":"高峰判定与异常核对","ai_hint":"先固定一个站点手算两个时段的上车总数，再与程序汇总对照。"}',
 'published','demo-course','teacher-demo'),
